		c8(c,0x31); c8(c,0xC0);
		c8(c,0x0F); c8(c,0x05);
		c8(c,0x48); c8(c,0x85); c8(c,0xC0);
		c8(c,0x7E); c8(c,0x05);
		c8(c,0x48); c8(c,0x01); c8(c,0xC5);
		c8(c,0xEB); c8(c,0xCF);
