	c8(c,0x74); c8(c,0x1C);
	c8(c,0x48); c8(c,0x81); c8(c,0xFA); c8(c,0x00); c8(c,0x00); c8(c,0x01); c8(c,0x00);
	c8(c,0x76); c8(c,0x05);
	c8(c,0xBA); c8(c,0x00); c8(c,0x00); c8(c,0x01); c8(c,0x00);
	c8(c,0x31); c8(c,0xC0);
