static int cnum(const char *s, uint64_t *v, int *neg) {
	*neg = 0;
	while(*s==' ') s++;
	if(*s=='-') {
		*neg = 1;
		s++;
	} else if(*s=='+') s++;
	if(!(*s>='0' && *s<='9')) return 0;
	char *e;
	errno = 0;
	uint64_t n = strtoull(s, &e, 10);
	if(errno) return 0;
	static const char *sx[] = {"", "b", "kB", "k", "K", "KiB", "MB", "M", "MiB", "m", "GB", "G", "GiB", "g", "TB", "T", "TiB", "t", "PB", "P", "PiB", "p", "EB", "E", "EiB", "e", NULL};
	static const uint64_t ml[] = {1, 512, 1000, 1024, 1024, 1024, 1000000ULL, 1ULL<<20, 1ULL<<20, 1ULL<<20, 1000000000ULL, 1ULL<<30, 1ULL<<30, 1ULL<<30, 1000000000000ULL, 1ULL<<40, 1ULL<<40, 1ULL<<40, 1000000000000000ULL, 1ULL<<50, 1ULL<<50, 1ULL<<50, 1000000000000000000ULL, 1ULL<<60, 1ULL<<60, 1ULL<<60};
	for(int k = 0; sx[k]; k++) {
		if(strcmp(e, sx[k])==0) {
			if(ml[k] && n>UINT64_MAX/ml[k]) n = UINT64_MAX;
			else n *= ml[k];
			*v = n;
			return 1;
		}
	}
	return 0;
}

static void theader(Code *c, Gen *g, const char *nm) {
	char hd[700];
	snprintf(hd, sizeof(hd), "\n==> %s <==\n", nm);
	c8(c,0x48); c8(c,0xBE); rels_add_here(g, cpos(c), add_str(g,hd)); c64(c,0);
	c8(c,0x48); c8(c,0xBA); c64(c,(uint64_t)strlen(hd));
	c8(c,0x48); c8(c,0xBF); c64(c,g->bss_base+g->scr_off+248);
	c8(c,0x80); c8(c,0x3F); c8(c,0x00);
	c8(c,0x75); c8(c,0x06);
	c8(c,0x48); c8(c,0xFF); c8(c,0xC6);
	c8(c,0x48); c8(c,0xFF); c8(c,0xCA);
	c8(c,0xC6); c8(c,0x07); c8(c,0x01);
	c8(c,0xBF); c8(c,0x01); c8(c,0x00); c8(c,0x00); c8(c,0x00);
	c8(c,0xB8); c8(c,0x01); c8(c,0x00); c8(c,0x00); c8(c,0x00);
	c8(c,0x0F); c8(c,0x05);
}

