static void wtab(Code *c, Gen *g, uint64_t at) {
	if(!g->wt_pos) {
		Buf b;
		binit(&b);
		char *ol = setlocale(LC_CTYPE, NULL);
		char *sv = ol ? strdup(ol) : NULL;
		if(!setlocale(LC_CTYPE, "C.UTF-8")) setlocale(LC_CTYPE, "en_US.UTF-8");
		int pw = -9;
		uint32_t st0 = 0;
		for(uint32_t u = 0xA0; u<=0x110000; u++) {
			int w = u<0x110000 ? wcwidth((wchar_t)u) : -9;
			if(u>=0xD800 && u<=0xDFFF) w = 0;
			if(w<0 && u<0x110000) w = 0;
			if(w!=pw) {
				if(pw==0 || pw==2) {
					uint32_t e[2] = {st0, (u-1) | ((uint32_t)pw<<24)};
					bput(&b, e, 8);
				}
				st0 = u;
				pw = w;
			}
		}
		setlocale(LC_CTYPE, sv ? sv : "C");
		free(sv);
		size_t j = jmp_rel32(c);
		g->wt_pos = cpos(c);
		g->wt_n = (int)(b.len/8);
		bput(&c->code, b.data, b.len);
		patch_here(c,j);
		free(b.data);
	}
	c8(c,0x48); c8(c,0x8D); c8(c,0x05); c32(c, (uint32_t)(g->wt_pos - (cpos(c)+4)));
	mov_rdi_imm64(c, at);
	c8(c,0x48); c8(c,0x89); c8(c,0x07);
	mov_rax_imm32(c, (uint32_t)g->wt_n);
	c8(c,0x48); c8(c,0x89); c8(c,0x47); c8(c,0x08);
}

