static uint32_t gmbc(const unsigned char *s, int n, int *len);

typedef struct {
	uint32_t lo, hi;
} GR;

typedef struct {
	GR *r;
	int n, c;
	uint8_t raw[16];
} GS;

static void gsadd(GS *s, uint32_t lo, uint32_t hi) {
	if(lo>hi) return;
	if(s->n==s->c) {
		s->c = s->c ? s->c*2 : 8;
		s->r = realloc(s->r, sizeof(GR)*(size_t)s->c);
	}
	s->r[s->n].lo = lo;
	s->r[s->n].hi = hi;
	s->n++;
}

static int grcmp(const void *a, const void *b) {
	const GR *x = a, *y = b;
	return x->lo<y->lo ? -1 : x->lo>y->lo;
}

static void gsnorm(GS *s) {
	if(s->n<2) return;
	qsort(s->r, (size_t)s->n, sizeof(GR), grcmp);
	int k = 0;
	for(int i = 1; i<s->n; i++) {
		if(s->r[i].lo<=s->r[k].hi+1) {
			if(s->r[i].hi>s->r[k].hi) s->r[k].hi = s->r[i].hi;
		} else s->r[++k] = s->r[i];
	}
	s->n = k+1;
}

static int gshas(const GS *s, uint32_t c) {
	int lo = 0, hi = s->n-1;
	while(lo<=hi) {
		int m = (lo+hi)/2;
		if(c<s->r[m].lo) hi = m-1;
		else if(c>s->r[m].hi) lo = m+1;
		else return 1;
	}
	return 0;
}

static void gsor(GS *d, const GS *s) {
	for(int i = 0; i<s->n; i++) gsadd(d, s->r[i].lo, s->r[i].hi);
	for(int i = 0; i<16; i++) d->raw[i] |= s->raw[i];
	gsnorm(d);
}

static void gsnot(GS *s) {
	gsnorm(s);
	GS t = {0};
	uint32_t p = 0;
	for(int i = 0; i<s->n; i++) {
		if(s->r[i].lo>p) gsadd(&t, p, s->r[i].lo-1);
		p = s->r[i].hi+1;
	}
	if(p<=0x110000) gsadd(&t, p, 0x110000);
	free(s->r);
	s->r = t.r;
	s->n = t.n;
	s->c = t.c;
}

static void gsfree(GS *s) {
	free(s->r);
	memset(s, 0, sizeof(*s));
}

static const int32_t *g_cst;
static const unsigned char *g_cse;
static int32_t g_csn;
static GS g_ucl[12];
static int g_uok[12];
static const char *g_ucn[12] = {"alpha","upper","lower","digit","xdigit","space","print","punct","graph","cntrl","blank","alnum"};
static uint32_t *g_iu;
static uint32_t *g_iuo;
static uint32_t *g_iul;
static const char *g_csq;

static int g_lat1, g_gnl;
static uint32_t gcsq(uint32_t wc) {
	if(g_lat1 || g_gnl) return wc;
	const uint32_t *t = (const uint32_t*)g_csq;
	if(!t) return ~0u;
	uint32_t i1 = wc>>t[0];
	if(i1<t[1]) {
		uint32_t l1 = t[5+i1];
		if(l1) {
			uint32_t i2 = (wc>>t[2]) & t[3];
			uint32_t l2 = ((const uint32_t*)(g_csq+l1))[i2];
			if(l2) return ((const uint32_t*)(g_csq+l2))[wc & t[4]];
		}
	}
	return ~0u;
}

static int gvalid(uint32_t c) {
	return c<0xD800 || (c>0xDFFF && c<=0x10FFFF);
}

static GS g_ucl1[12];
static int g_uok1[12];
static GS *gucls(int k) {
	if(g_lat1) {
		if(!g_uok1[k]) {
			wctype_t w = wctype(g_ucn[k]);
			for(uint32_t c = 0; c<0x80; c++) if(iswctype((wint_t)c, w)) gsadd(&g_ucl1[k], c, c);
			gsnorm(&g_ucl1[k]);
			g_uok1[k] = 1;
		}
		return &g_ucl1[k];
	}
	if(!g_uok[k]) {
		wctype_t w = wctype(g_ucn[k]);
		uint32_t st = 0;
		int in = 0;
		for(uint32_t c = 0; c<=0x110000; c++) {
			int x = c<0x110000 && gvalid(c) && iswctype((wint_t)c, w);
			if(x && !in) {
				st = c;
				in = 1;
			} else if(!x && in) {
				gsadd(&g_ucl[k], st, c-1);
				in = 0;
			}
		}
		g_uok[k] = 1;
	}
	return &g_ucl[k];
}

static uint32_t gup(uint32_t c) {
	if(g_lat1) return c>='a' && c<='z' ? c-32 : c;
	if(!gvalid(c)) return c;
	return (uint32_t)towupper((wint_t)c);
}

