static void ginv(void) {
	if(g_iu) return;
	uint32_t n = 0;
	for(uint32_t c = 0; c<0x110000; c++) if(gvalid(c) && gup(c)!=c) n++;
	g_iu = malloc(sizeof(uint32_t)*n*2+8);
	uint32_t k = 0;
	for(uint32_t c = 0; c<0x110000; c++) if(gvalid(c) && gup(c)!=c) {
		g_iu[k*2] = gup(c);
		g_iu[k*2+1] = c;
		gsadd(&g_chg, c, c);
		k++;
	}
	gsnorm(&g_chg);
	g_iuo = g_iu;
	g_iul = g_iu+(size_t)k*2;
	g_chok = 1;
}

static void gfold(GS *d, const GS *s) {
	if(g_lat1) {
		GS t = {0};
		for(int i = 0; i<s->n; i++) gsadd(&t, s->r[i].lo, s->r[i].hi);
		for(uint32_t c = 'a'; c<='z'; c++) if(gshas(s, c-32)) gsadd(&t, c, c);
		memcpy(t.raw, s->raw, 16);
		gsnorm(&t);
		free(d->r);
		*d = t;
		return;
	}
	ginv();
	GS t = {0};
	int j = 0;
	for(int i = 0; i<s->n; i++) {
		uint32_t lo = s->r[i].lo, hi = s->r[i].hi;
		while(j<g_chg.n && g_chg.r[j].hi<lo) j++;
		int k = j;
		uint32_t a = lo;
		while(a<=hi) {
			while(k<g_chg.n && g_chg.r[k].hi<a) k++;
			if(k>=g_chg.n || g_chg.r[k].lo>hi) {
				gsadd(&t, a, hi);
				break;
			}
			if(g_chg.r[k].lo>a) gsadd(&t, a, g_chg.r[k].lo-1);
			if(g_chg.r[k].hi>=hi) break;
			a = g_chg.r[k].hi+1;
		}
	}
	for(uint32_t *q = g_iuo; q<g_iul; q += 2) if(gshas(s, q[0])) gsadd(&t, q[1], q[1]);
	memcpy(t.raw, s->raw, 16);
	gsnorm(&t);
	free(d->r);
	*d = t;
}

static const unsigned char *g_csm;

static void gcinit(void) {
	if(g_ct) return;
	uint32_t nr = (uint32_t)(uintptr_t)nl_langinfo(_NL_COLLATE_NRULES);
	if(nr==0) return;
	g_ct = (const int32_t*)nl_langinfo(_NL_COLLATE_TABLEMB);
	g_cx = (const unsigned char*)nl_langinfo(_NL_COLLATE_EXTRAMB);
	g_ci = (const int32_t*)nl_langinfo(_NL_COLLATE_INDIRECTMB);
	g_csq = nl_langinfo(_NL_COLLATE_COLLSEQWC);
	g_csm = (const unsigned char*)nl_langinfo(_NL_COLLATE_COLLSEQMB);
	g_csn = (int32_t)(uintptr_t)nl_langinfo(_NL_COLLATE_SYMB_HASH_SIZEMB);
	g_cst = (const int32_t*)nl_langinfo(_NL_COLLATE_SYMB_TABLEMB);
	g_cse = (const unsigned char*)nl_langinfo(_NL_COLLATE_SYMB_EXTRAMB);
}

enum {GT_END, GT_CH, GT_RAW, GT_ALT, GT_STAR, GT_PLUS, GT_QM, GT_OBR, GT_OSUB, GT_CSUB, GT_ODUP, GT_CDUP, GT_BREF, GT_ANC, GT_DOT, GT_WORD, GT_NWORD, GT_SPC, GT_NSPC, GT_BSL};

enum {AN_LF, AN_LL, AN_BF, AN_BL, AN_WF, AN_WL, AN_WD, AN_NWD, AN_IW, AN_INW};

enum {GN_CH, GN_CAT, GN_ALT, GN_STAR, GN_SUB, GN_BREF, GN_ANC};

typedef struct {
	int t, a, b, v;
} GN;

typedef struct {
	int t;
	int c;
	uint32_t cp;
	int v;
} GTk;

typedef struct {
	uint32_t *ocp;
	uint32_t *ucp;
	uint8_t *ob;
	uint8_t *ub;
	uint8_t *raw;
	int n, i;
	int ere, icase;
	unsigned long syn;
	GN *nd;
	int nn, cn;
	GS *sets;
	int ns, cs;
	int nsub, done, used, nbr;
	int err;
	int dfam, adup, uns, unb;
} GP;

#define RE_DUPM 0x7fff

static int gpn(GP *p, int t, int a, int b, int v) {
	if(p->nn==p->cn) {
		p->cn = p->cn ? p->cn*2 : 64;
		p->nd = realloc(p->nd, sizeof(GN)*(size_t)p->cn);
	}
	p->nd[p->nn].t = t;
	p->nd[p->nn].a = a;
	p->nd[p->nn].b = b;
	p->nd[p->nn].v = v;
	return p->nn++;
}

static int gpset(GP *p, GS *s) {
	if(p->ns==p->cs) {
		p->cs = p->cs ? p->cs*2 : 16;
		p->sets = realloc(p->sets, sizeof(GS)*(size_t)p->cs);
	}
	p->sets[p->ns] = *s;
	return p->ns++;
}

static int gpeek(GP *p, int at, GTk *t, int anch) {
	t->v = 0;
	t->cp = 0;
	if(at>=p->n) {
		t->t = GT_END;
		return 0;
	}
	int c = p->ub[at];
	t->c = c;
	t->cp = p->ucp[at];
	if(p->raw[at]) {
		t->t = GT_CH;
		return 1;
	}
	if(p->ocp[at]>=0x80) {
		t->t = GT_CH;
		return 1;
	}
	if(c=='\\') {
		if(at+1>=p->n) {
			t->t = GT_BSL;
			return 1;
		}
		int c2 = p->ob[at+1];
		t->c = c2;
		t->cp = g_gnl ? p->ocp[at+1] : p->ucp[at+1];
		t->t = GT_CH;
		if(p->raw[at+1] || p->ocp[at+1]>=0x80) return 2;
		unsigned long y = p->syn;
		int go = !(y & RE_NO_GNU_OPS);
		switch(c2) {
		case '|': if(!(y & RE_LIMITED_OPS) && !(y & RE_NO_BK_VBAR)) t->t = GT_ALT; break;
		case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9':
			if(y & RE_NO_BK_REFS) break;
			t->t = GT_BREF;
			t->v = c2-'1';
			break;
		case '<': if(go) { t->t = GT_ANC; t->v = AN_WF; } break;
		case '>': if(go) { t->t = GT_ANC; t->v = AN_WL; } break;
		case 'b': if(go) { t->t = GT_ANC; t->v = AN_WD; } break;
		case 'B': if(go) { t->t = GT_ANC; t->v = AN_NWD; } break;
		case 'w': if(go) t->t = GT_WORD; break;
		case 'W': if(go) t->t = GT_NWORD; break;
		case 's': if(go) t->t = GT_SPC; break;
		case 'S': if(go) t->t = GT_NSPC; break;
		case '`': if(go) { t->t = GT_ANC; t->v = AN_BF; } break;
		case '\'': if(go) { t->t = GT_ANC; t->v = AN_BL; } break;
		case '(': if(!(y & RE_NO_BK_PARENS)) t->t = GT_OSUB; break;
		case ')': if(!(y & RE_NO_BK_PARENS)) t->t = GT_CSUB; break;
		case '+': if(!(y & RE_LIMITED_OPS) && (y & RE_BK_PLUS_QM)) t->t = GT_PLUS; break;
		case '?': if(!(y & RE_LIMITED_OPS) && (y & RE_BK_PLUS_QM)) t->t = GT_QM; break;
		case '{': if((y & RE_INTERVALS) && !(y & RE_NO_BK_BRACES)) t->t = GT_ODUP; break;
		case '}': if((y & RE_INTERVALS) && !(y & RE_NO_BK_BRACES)) t->t = GT_CDUP; break;
		}
		return 2;
	}
	t->t = GT_CH;
	unsigned long y = p->syn;
	switch(c) {
	case '\n': if(y & RE_NEWLINE_ALT) t->t = GT_ALT; break;
	case '|': if(!(y & RE_LIMITED_OPS) && (y & RE_NO_BK_VBAR)) t->t = GT_ALT; break;
	case '*': t->t = GT_STAR; break;
	case '+': if(!(y & RE_LIMITED_OPS) && !(y & RE_BK_PLUS_QM)) t->t = GT_PLUS; break;
	case '?': if(!(y & RE_LIMITED_OPS) && !(y & RE_BK_PLUS_QM)) t->t = GT_QM; break;
	case '{': if((y & RE_INTERVALS) && (y & RE_NO_BK_BRACES)) t->t = GT_ODUP; break;
	case '}': if((y & RE_INTERVALS) && (y & RE_NO_BK_BRACES)) t->t = GT_CDUP; break;
	case '(': if(y & RE_NO_BK_PARENS) t->t = GT_OSUB; break;
	case ')': if(y & RE_NO_BK_PARENS) t->t = GT_CSUB; break;
	case '[': t->t = GT_OBR; break;
	case '.': t->t = GT_DOT; break;
	case '^':
		if(!(y & (RE_CONTEXT_INDEP_ANCHORS | RE_CARET_ANCHORS_HERE)) && !anch && at!=0) {
			if(!(y & RE_NEWLINE_ALT) || p->ub[at-1]!='\n') break;
		}
		t->t = GT_ANC;
		t->v = AN_LF;
		break;
	case '$':
		if(!(y & RE_CONTEXT_INDEP_ANCHORS) && at+1!=p->n) {
			GTk nx;
			gpeek(p, at+1, &nx, 0);
			if(nx.t!=GT_ALT && nx.t!=GT_CSUB) break;
		}
		t->t = GT_ANC;
		t->v = AN_LL;
		break;
	}
	return 1;
}

static void gfetch(GP *p, GTk *t, int anch) {
	p->i += gpeek(p, p->i, t, anch);
}

static void gchset(GP *p, GS *s, uint32_t cp, int raw) {
	memset(s, 0, sizeof(*s));
	if(raw) {
		s->raw[(cp-0x80)>>3] |= (uint8_t)(1<<((cp-0x80) & 7));
		return;
	}
	gsadd(s, cp, cp);
	if(p->icase) gfold(s, s);
}

static int gleaf(GP *p, GS *s) {
	if(p->icase) {
		GS t = {0};
		gsor(&t, s);
		gfold(&t, &t);
		gsfree(s);
		*s = t;
	}
	return gpn(p, GN_CH, 0, 0, gpset(p, s));
}

enum {BE_SB, BE_MB, BE_EQ, BE_COLL, BE_CLS};

typedef struct {
	int t;
	uint32_t cp;
	char name[40];
	int raw;
} GBE;

static int gpbt(GP *p, int at, GTk *t) {
	if(at>=p->n) {
		t->t = GT_END;
		return 0;
	}
	int c = p->ub[at];
	t->c = c;
	t->v = 0;
	if(p->raw[at] || p->ocp[at]>=0x80) {
		t->t = GT_CH;
		return 1;
	}
	if(c=='\\' && (p->syn & RE_BACKSLASH_ESCAPE_IN_LISTS) && at+1<p->n) {
		t->t = GT_CH;
		t->c = p->ub[at+1];
		t->v = 1;
		return 2;
	}
	if(c=='[') {
		int c2 = at+1<p->n ? p->ub[at+1] : 0;
		if(at+1<p->n && (p->raw[at+1] || p->ocp[at+1]>=0x80)) c2 = 0;
		t->c = c2;
		if(c2=='.') { t->t = 100; return 2; }
		if(c2=='=') { t->t = 101; return 2; }
		if(c2==':' && (p->syn & RE_CHAR_CLASSES)) { t->t = 102; return 2; }
		t->t = GT_CH;
		t->c = c;
		return 1;
	}
	switch(c) {
	case '-': t->t = 103; break;
	case ']': t->t = 104; break;
	case '^': t->t = 105; break;
	default: t->t = GT_CH;
	}
	return 1;
}

static int gpbsym(GP *p, GBE *e, int delim, int kind) {
	unsigned char bs[256];
	int nb = 0, ui[256];
	for(int u = p->i; u<p->n && nb<250; u++) {
		char buf[8];
		int l;
		if(p->raw[u]) {
			buf[0] = (char)p->ob[u];
			l = 1;
		} else l = u8enc(kind==102 ? p->ocp[u] : p->ucp[u], buf);
		for(int k = 0; k<l; k++) {
			bs[nb] = (unsigned char)buf[k];
			ui[nb] = k==l-1 ? u+1 : -1;
			nb++;
		}
	}
	int j = 0, i = 0;
	if(j>=nb) return 7;
	for(;; i++) {
		if(i>=32) return 7;
		unsigned char ch = bs[j++];
		if(j>=nb) return 7;
		if(ch==delim && bs[j]==']') break;
		e->name[i] = (char)ch;
	}
	j++;
	e->name[i] = 0;
	int u = p->i;
	for(int k = 0; k<j; k++) if(ui[k]>=0) u = ui[k];
	p->i = u;
	e->t = kind==100 ? BE_COLL : kind==101 ? BE_EQ : BE_CLS;
	return 0;
}

static int gpbel(GP *p, GBE *e, GTk *t, int tl, int acch) {
	if(t->t==GT_CH && t->v==1) {
		p->i++;
		tl = 1;
	}
	if(!p->raw[p->i] && p->ocp[p->i]>=0x80) {
		e->t = BE_MB;
		e->cp = p->ucp[p->i];
		e->raw = 0;
		p->i++;
		return 0;
	}
	p->i += tl;
	if(t->t==100 || t->t==101 || t->t==102) return gpbsym(p, e, t->c, t->t);
	if(t->t==103 && !acch) {
		GTk t2;
		gpbt(p, p->i, &t2);
		if(t2.t!=104) return 11;
	}
	e->t = BE_SB;
	e->raw = p->raw[p->i-tl];
	e->cp = e->raw ? p->ob[p->i-tl] : (uint32_t)t->c;
	if(!e->raw && t->t==GT_CH && tl==1) e->cp = p->ucp[p->i-1];
	return 0;
}


static int gcsym(const char *name) {
	size_t l = strlen(name);
	for(int32_t e = 0; e<g_csn; e++) if(g_cst[2*e]) {
		int32_t idx = g_cst[2*e+1];
		idx += 1+g_cse[idx];
		if(l==g_cse[idx] && memcmp(name, &g_cse[idx+1], l)==0) return e;
	}
	return -1;
}

static uint32_t gbcsq(GBE *e) {
	if(g_lat1 || g_gnl) {
		if(e->t==BE_SB || e->t==BE_MB) return e->cp;
		if(e->t==BE_COLL && strlen(e->name)==1) return (unsigned char)e->name[0];
		return ~0u;
	}
	if(e->t==BE_SB) {
		if(e->raw) return ~0u;
		return gcsq(e->cp);
	}
	if(e->t==BE_MB) return gcsq(e->cp);
	if(e->t==BE_COLL) {
		size_t l = strlen(e->name);
		int el = gcsym(e->name);
		if(el!=-1) {
			int32_t idx = g_cst[2*el+1];
			idx += 1+g_cse[idx];
			idx += 1+g_cse[idx];
			idx = (idx+3) & ~3;
			idx += 4;
			idx += 4*(1+*(const uint32_t*)(g_cse+idx));
			return *(const uint32_t*)(g_cse+idx);
		}
		if(l==1 && g_csm) return g_csm[(unsigned char)e->name[0]];
	}
	return ~0u;
}

static int geqw(uint32_t cp, int32_t *ix) {
	char s[8];
	int l = u8enc(cp, s);
	s[l] = 0;
	const unsigned char *q = (const unsigned char*)s;
	*ix = cfind(&q);
	return (int)(q-(const unsigned char*)s)==l;
}

static int gbeq(GP *p, GS *s, const char *name) {
	(void)p;
	if(g_lat1 || g_gnl) {
		if(strlen(name)!=1) return 3;
		gsadd(s, (unsigned char)name[0], (unsigned char)name[0]);
		return 0;
	}
	if(!g_ct) return 13;
	const unsigned char *q = (const unsigned char*)name;
	int32_t i1 = cfind(&q);
	if(i1==0 || *q) return 13;
	const unsigned char *wt = (const unsigned char*)nl_langinfo(_NL_COLLATE_WEIGHTMB);
	size_t len = wt[i1 & 0xffffff];
	for(uint32_t c = 0; c<0x110000; c++) {
		if(!gvalid(c)) continue;
		int32_t i2;
		if(!geqw(c, &i2)) continue;
		if((i2 & 0xffffff)==0) continue;
		if(len==wt[i2 & 0xffffff] && (i1>>24)==(i2>>24) && memcmp(wt+(i1 & 0xffffff)+1, wt+(i2 & 0xffffff)+1, len)==0) gsadd(s, c, c);
	}
	return 0;
}

static int gbcls(GP *p, GS *s, const char *name) {
	const char *nm = name;
	if(p->icase && (strcmp(nm,"upper")==0 || strcmp(nm,"lower")==0)) nm = "alpha";
	for(int k = 0; k<12; k++) if(strcmp(nm, g_ucn[k])==0) {
		GS *u = gucls(k);
		for(int i = 0; i<u->n; i++) gsadd(s, u->r[i].lo, u->r[i].hi);
		return 0;
	}
	return 4;
}

static int gbrack(GP *p, int *out) {
	GS s = {0};
	GTk t;
	int nm = 0, first = 1;
	int tl = gpbt(p, p->i, &t);
	if(t.t==GT_END) return 2;
	if(t.t==105) {
		p->uns = 1;
		nm = 1;
		if(p->syn & RE_HAT_LISTS_NOT_NEWLINE) gsadd(&s, '\n', '\n');
		p->i += tl;
		tl = gpbt(p, p->i, &t);
		if(t.t==GT_END) return 2;
	}
	if(t.t==104) t.t = GT_CH;
	for(;;) {
		GBE a, b;
		memset(&a, 0, sizeof(a));
		memset(&b, 0, sizeof(b));
		a.t = BE_COLL;
		int r = gpbel(p, &a, &t, tl, first);
		if(r) { gsfree(&s); return r; }
		first = 0;
		tl = gpbt(p, p->i, &t);
		int rng = 0;
		GTk t2;
		int tl2 = 0;
		if(a.t!=BE_CLS && a.t!=BE_EQ) {
			if(t.t==GT_END) { gsfree(&s); return 7; }
			if(t.t==103) {
				p->i += tl;
				tl2 = gpbt(p, p->i, &t2);
				if(t2.t==GT_END) { gsfree(&s); return 7; }
				if(t2.t==104) {
					p->i -= tl;
					t.t = GT_CH;
				} else rng = 1;
			}
		}
		if(rng) {
			p->unb = p->uns;
			p->uns = 1;
			b.t = BE_COLL;
			r = gpbel(p, &b, &t2, tl2, 1);
			if(r) { gsfree(&s); return r; }
			tl = gpbt(p, p->i, &t);
			if(a.t==BE_EQ || a.t==BE_CLS || b.t==BE_EQ || b.t==BE_CLS) { gsfree(&s); return 11; }
			if(a.t==BE_SB && b.t==BE_SB && !a.raw && !b.raw && a.cp>='0' && a.cp<='9' && b.cp>='0' && b.cp<='9' ) p->uns = p->unb;
			uint32_t sc = gbcsq(&a), ec = gbcsq(&b);
			if(sc==~0u || ec==~0u) { gsfree(&s); return 3; }
			if(sc>ec && (p->syn & RE_NO_EMPTY_RANGES)) { gsfree(&s); return 11; }
			if(sc<=ec) for(uint32_t c = 0; c<0x110000; c++) {
				if(!gvalid(c)) continue;
				uint32_t q = gcsq(c);
				if(q>=sc && q<=ec) gsadd(&s, c, c);
			}
			gsnorm(&s);
		} else {
			switch(a.t) {
			case BE_SB:
				if(a.raw) p->uns = 1;
				if(!a.raw && a.cp<0x80) {
					gsadd(&s, a.cp, a.cp);
					if(p->icase) {
						GS f = {0};
						gsadd(&f, a.cp, a.cp);
						gfold(&f, &f);
						if(f.n && f.r[f.n-1].hi>=0x80) p->uns = 1;
						gsfree(&f);
					}
				}
				break;
			case BE_MB:
				p->uns = 1;
				gsadd(&s, a.cp, a.cp);
				break;
			case BE_EQ:
				p->uns = 1;
				r = gbeq(p, &s, a.name);
				if(r) { gsfree(&s); return r; }
				break;
			case BE_COLL:
				p->uns = 1;
				if((g_lat1 || g_gnl) && strlen(a.name)!=1) { gsfree(&s); return 3; }
				if(!g_lat1 && !g_gnl && gcsym(a.name)!=-1) {
					size_t l = strlen(a.name);
					uint32_t cp;
					if(l==1) gsadd(&s, (unsigned char)a.name[0], (unsigned char)a.name[0]);
					else {
						const unsigned char *u = (const unsigned char*)a.name;
						int q;
						cp = gmbc(u, (int)l, &q);
						if(q==(int)l) gsadd(&s, cp, cp);
					}
				} else if(strlen(a.name)==1) {
					unsigned char ch = (unsigned char)a.name[0];
					if(ch<0x80) gsadd(&s, ch, ch);
				} else { gsfree(&s); return 3; }
				break;
			case BE_CLS:
				if(strcmp(a.name,"digit") && strcmp(a.name,"xdigit")) p->uns = 1;
				r = gbcls(p, &s, a.name);
				if(r) { gsfree(&s); return r; }
				break;
			}
		}
		if(t.t==GT_END) { gsfree(&s); return 7; }
		if(t.t==104) break;
	}
	p->i += tl;
	gsnorm(&s);
	memset(s.raw, 0, 16);
	if(nm) gsnot(&s);
	*out = gleaf(p, &s);
	return 0;
}

static int gpreg(GP *p, GTk *t, int nest, int *out);

static int gpdup(GP *p, int elem, GTk *t, int *out) {
	int st, en, si = p->i;
	GTk s0 = *t;
	if(t->t==GT_ODUP) {
		en = 0;
		int num = -1;
		for(;;) {
			gfetch(p, t, 0);
			if(t->t==GT_END) { num = -2; break; }
			if(t->t==GT_CDUP || t->c==',') break;
			num = (t->t!=GT_CH || t->c<'0' || t->c>'9' || num==-2) ? -2 : num==-1 ? t->c-'0' : (num*10+t->c-'0'>RE_DUPM+1 ? RE_DUPM+1 : num*10+t->c-'0');
		}
		st = num;
		if(st==-1) {
			if(t->t==GT_CH && t->c==',') st = 0;
			else return 10;
		}
		if(st!=-2) {
			if(t->t==GT_CDUP) en = st;
			else if(t->t==GT_CH && t->c==',') {
				int n2 = -1;
				for(;;) {
					gfetch(p, t, 0);
					if(t->t==GT_END) { n2 = -2; break; }
					if(t->t==GT_CDUP || t->c==',') break;
					n2 = (t->t!=GT_CH || t->c<'0' || t->c>'9' || n2==-2) ? -2 : n2==-1 ? t->c-'0' : (n2*10+t->c-'0'>RE_DUPM+1 ? RE_DUPM+1 : n2*10+t->c-'0');
				}
				en = n2;
			} else en = -2;
		}
		if(st==-2 || en==-2) {
			if(!(p->syn & RE_INVALID_INTERVAL_ORD)) return t->t==GT_END ? 9 : 10;
			p->i = si;
			*t = s0;
			t->t = GT_CH;
			*out = elem;
			return -1;
		}
		if((en!=-1 && st>en) || t->t!=GT_CDUP) return 10;
		if((en==-1 ? st : en)>RE_DUPM) return 15;
	} else {
		st = t->t==GT_PLUS ? 1 : 0;
		en = t->t==GT_QM ? 1 : -1;
	}
	gfetch(p, t, 0);
	if(elem<0) { *out = -1; return 0; }
	if(st==0 && en==0) { *out = -1; return 0; }
	if((long)(st>en ? st : en)*p->nn>4000000) return 12;
	int tree = -1, old = -1;
	if(st>0) {
		tree = elem;
		for(int i = 2; i<=st; i++) tree = gpn(p, GN_CAT, tree, elem, 0);
		if(st==en) { *out = tree; return 0; }
		old = tree;
	}
	if(en==-1) tree = gpn(p, GN_STAR, elem, -1, 0);
	else {
		tree = gpn(p, GN_ALT, elem, -1, 0);
		for(int i = st+2; i<=en; i++) {
			tree = gpn(p, GN_CAT, tree, elem, 0);
			tree = gpn(p, GN_ALT, tree, -1, 0);
		}
	}
	if(old>=0) tree = gpn(p, GN_CAT, old, tree, 0);
	*out = tree;
	return 0;
}

static int gpexp(GP *p, GTk *t, int nest, int *out) {
	int tree = -1, r;
	GS s;
	switch(t->t) {
	case GT_CH:
		if(p->raw[p->i-1]) {
			memset(&s, 0, sizeof(s));
			uint32_t b = p->ob[p->i-1];
			s.raw[(b-0x80)>>3] |= (uint8_t)(1<<((b-0x80) & 7));
		} else gchset(p, &s, t->cp, 0);
		tree = gpn(p, GN_CH, 0, 0, gpset(p, &s));
		break;
	case GT_OSUB: {
		int cur = p->nsub++;
		gfetch(p, t, 1);
		int sub = -1;
		if(t->t!=GT_CSUB) {
			r = gpreg(p, t, nest+1, &sub);
			if(r) return r;
			if(t->t!=GT_CSUB) return 8;
		}
		if(cur<=8) p->done |= 1<<cur;
		tree = gpn(p, GN_SUB, sub, -1, cur);
		break;
	}
	case GT_OBR:
		r = gbrack(p, &tree);
		if(r) return r;
		break;
	case GT_BREF:
		p->uns = 1;
		if(!(p->done & (1<<t->v))) return 6;
		p->used |= 1<<t->v;
		p->nbr++;
		tree = gpn(p, GN_BREF, 0, 0, t->v);
		break;
	case GT_ODUP:
	case GT_STAR:
	case GT_PLUS:
	case GT_QM:
		if(t->t==GT_ODUP && (p->syn & RE_CONTEXT_INVALID_DUP)) return 13;
		if(p->syn & RE_CONTEXT_INVALID_OPS) return 13;
		if(p->syn & RE_CONTEXT_INDEP_OPS) {
			gfetch(p, t, 0);
			return gpexp(p, t, nest, out);
		}
		if(t->t==GT_ODUP) t->c = '{';
		else if(t->t==GT_PLUS) t->c = '+';
		else if(t->t==GT_QM) t->c = '?';
		else t->c = '*';
		gchset(p, &s, (uint32_t)t->c, 0);
		tree = gpn(p, GN_CH, 0, 0, gpset(p, &s));
		break;
	case GT_CSUB:
		if(!(p->syn & RE_UNMATCHED_RIGHT_PAREN_ORD)) return 16;
		gchset(p, &s, ')', 0);
		tree = gpn(p, GN_CH, 0, 0, gpset(p, &s));
		break;
	case GT_CDUP:
		gchset(p, &s, '}', 0);
		tree = gpn(p, GN_CH, 0, 0, gpset(p, &s));
		break;
	case GT_ANC:
		if(t->v==AN_WD) tree = gpn(p, GN_ALT, gpn(p, GN_ANC, 0, 0, AN_WF), gpn(p, GN_ANC, 0, 0, AN_WL), 0);
		else if(t->v==AN_NWD) tree = gpn(p, GN_ALT, gpn(p, GN_ANC, 0, 0, AN_IW), gpn(p, GN_ANC, 0, 0, AN_INW), 0);
		else tree = gpn(p, GN_ANC, 0, 0, t->v);
		if(t->v!=AN_LF && t->v!=AN_LL && t->v!=AN_BF && t->v!=AN_BL) p->uns = 1;
		gfetch(p, t, 0);
		if(p->ere && (t->t==GT_STAR || t->t==GT_PLUS || t->t==GT_QM || t->t==GT_ODUP)) {
			p->adup = 1;
			if(p->dfam) break;
		}
		*out = tree;
		return 0;
	case GT_DOT:
		memset(&s, 0, sizeof(s));
		gsadd(&s, (p->syn & RE_DOT_NOT_NULL) ? 1 : 0, 9);
		gsadd(&s, (p->syn & RE_DOT_NEWLINE) ? 10 : 11, 0xD7FF);
		gsadd(&s, 0xE000, 0x10FFFF);
		tree = gleaf(p, &s);
		break;
	case GT_WORD:
	case GT_NWORD:
		memset(&s, 0, sizeof(s));
		p->uns = 1;
		{
			GS *u = gucls(11);
			for(int i = 0; i<u->n; i++) gsadd(&s, u->r[i].lo, u->r[i].hi);
			gsadd(&s, '_', '_');
			gsnorm(&s);
			if(t->t==GT_NWORD) gsnot(&s);
		}
		tree = gleaf(p, &s);
		break;
	case GT_SPC:
	case GT_NSPC:
		memset(&s, 0, sizeof(s));
		p->uns = 1;
		{
			GS *u = gucls(5);
			for(int i = 0; i<u->n; i++) gsadd(&s, u->r[i].lo, u->r[i].hi);
			gsnorm(&s);
			if(t->t==GT_NSPC) gsnot(&s);
		}
		tree = gleaf(p, &s);
		break;
	case GT_ALT:
	case GT_END:
		*out = -1;
		return 0;
	case GT_BSL:
		return 5;
	}
	if(!(t->t==GT_STAR || t->t==GT_PLUS || t->t==GT_QM || t->t==GT_ODUP) || p->nd[tree].t!=GN_ANC || !p->dfam) gfetch(p, t, 0);
	while(t->t==GT_STAR || t->t==GT_PLUS || t->t==GT_QM || t->t==GT_ODUP) {
		int nt;
		r = gpdup(p, tree, t, &nt);
		if(r==-1) {
			*out = tree;
			return 0;
		}
		if(r) return r;
		tree = nt;
		if((p->syn & RE_CONTEXT_INVALID_DUP) && (t->t==GT_STAR || t->t==GT_ODUP)) return 13;
	}
	*out = tree;
	return 0;
}

static int gpbranch(GP *p, GTk *t, int nest, int *out) {
	int tree, e, r;
	r = gpexp(p, t, nest, &tree);
	if(r) return r;
	while(t->t!=GT_ALT && t->t!=GT_END && (nest==0 || t->t!=GT_CSUB)) {
		r = gpexp(p, t, nest, &e);
		if(r) return r;
		if(tree>=0 && e>=0) tree = gpn(p, GN_CAT, tree, e, 0);
		else if(tree<0) tree = e;
	}
	*out = tree;
	return 0;
}

static int gpreg(GP *p, GTk *t, int nest, int *out) {
	int tree, br, r;
	int init = p->done;
	r = gpbranch(p, t, nest, &tree);
	if(r) return r;
	while(t->t==GT_ALT) {
		gfetch(p, t, 1);
		if(t->t!=GT_ALT && t->t!=GT_END && (nest==0 || t->t!=GT_CSUB)) {
			int acc = p->done;
			p->done = init;
			r = gpbranch(p, t, nest, &br);
			if(r) return r;
			p->done |= acc;
		} else br = -1;
		tree = gpn(p, GN_ALT, tree, br, 0);
	}
	*out = tree;
	return 0;
}

static const char *g_rerr[] = {"Success","No match","Invalid regular expression","Invalid collation character","Invalid character class name","Trailing backslash","Invalid back reference","Unmatched [, [^, [:, [., or [=","Unmatched ( or \\(","Unmatched \\{","Invalid content of \\{\\}","Invalid range end","Memory exhausted","Invalid preceding regular expression","Premature end of regular expression","Regular expression too big","Unmatched ) or \\)"};

static uint32_t gmbc(const unsigned char *s, int n, int *len) {
	mbstate_t st;
	memset(&st, 0, sizeof(st));
	wchar_t w = 0;
	size_t r = mbrtowc(&w, (const char*)s, (size_t)n, &st);
	if(r==(size_t)-1 || r==(size_t)-2 || r==0) {
		*len = r==0 ? 1 : -1;
		return 0;
	}
	*len = (int)r;
	return (uint32_t)w>0x10FFFF ? 0x110000 : (uint32_t)w;
}

static void gpsrc(GP *p, const unsigned char *s, int n) {
	free(p->ocp);
	free(p->ucp);
	free(p->ob);
	free(p->ub);
	free(p->raw);
	p->ocp = malloc(sizeof(uint32_t)*(size_t)(n+1));
	p->ucp = malloc(sizeof(uint32_t)*(size_t)(n+1));
	p->ob = malloc((size_t)n+1);
	p->ub = malloc((size_t)n+1);
	p->raw = malloc((size_t)n+1);
	int k = 0;
	for(int i = 0; i<n; ) {
		int l;
		uint32_t cp = g_lat1 ? s[i] : gmbc(s+i, n-i, &l);
		if(g_lat1) l = 1;
		if(l<=0) {
			p->ocp[k] = s[i];
			p->ucp[k] = s[i];
			p->ob[k] = s[i];
			p->ub[k] = s[i];
			p->raw[k] = s[i]>=0x80;
			k++;
			i++;
			continue;
		}
		p->ocp[k] = cp;
		p->ucp[k] = p->icase ? gup(cp) : cp;
		p->ob[k] = s[i];
		p->ub[k] = p->ucp[k]<0x80 ? (uint8_t)p->ucp[k] : 0x80;
		p->raw[k] = 0;
		k++;
		i += l;
	}
	p->n = k;
	p->i = 0;
	p->nsub = 0;
	p->done = 0;
	p->used = 0;
	p->nbr = 0;
}

static void gpinit(GP *p, int ere, int icase) {
	memset(p, 0, sizeof(*p));
	p->ere = ere;
	p->icase = icase;
	p->syn = ere ? (RE_CHAR_CLASSES|RE_DOT_NEWLINE|RE_INTERVALS|RE_NO_EMPTY_RANGES|RE_CONTEXT_INDEP_ANCHORS|RE_CONTEXT_INDEP_OPS|RE_NO_BK_BRACES|RE_NO_BK_PARENS|RE_NO_BK_VBAR|RE_UNMATCHED_RIGHT_PAREN_ORD|RE_INVALID_INTERVAL_ORD|RE_NEWLINE_ALT) : (RE_CHAR_CLASSES|RE_DOT_NEWLINE|RE_INTERVALS|RE_NO_EMPTY_RANGES|RE_BK_PLUS_QM|RE_NEWLINE_ALT);
}

static void gpfree(GP *p) {
	free(p->ocp);
	free(p->ucp);
	free(p->ob);
	free(p->ub);
	free(p->raw);
}

static int gparse(GP *p, int *root) {
	GTk t;
	gfetch(p, &t, 1);
	int r = gpreg(p, &t, 0, root);
	if(r) return r;
	return 0;
}

enum {NN_CH, NN_SPL, NN_JMP, NN_ASS, NN_MAT, NN_SAV, NN_BR};

typedef struct {
	int t, o1, o2, v;
} NN;

typedef struct {
	NN *n;
	int nn, cn;
} NF;

static int nfn(NF *f, int t, int o1, int o2, int v) {
	if(f->nn==f->cn) {
		f->cn = f->cn ? f->cn*2 : 256;
		f->n = realloc(f->n, sizeof(NN)*(size_t)f->cn);
	}
	f->n[f->nn].t = t;
	f->n[f->nn].o1 = o1;
	f->n[f->nn].o2 = o2;
	f->n[f->nn].v = v;
	return f->nn++;
}

static int g_fm;
static int gamask(int an) {
	int m = 0;
	if(g_fm) {
		for(int pv = 0; pv<4; pv++) for(int q = 0; q<4; q++) {
			int ok = 0;
			switch(an) {
			case AN_LF: ok = pv==0 || pv==3; break;
			case AN_BF: ok = pv==0; break;
			case AN_LL: ok = q<=1; break;
			case AN_BL: ok = q==0; break;
			case AN_WF: ok = pv!=1 && q==2; break;
			case AN_WL: ok = pv==1 && q!=2; break;
			case AN_IW: ok = pv==1 && q==2; break;
			case AN_INW: ok = pv!=1 && q!=2; break;
			}
			if(ok) m |= 1<<(pv*4+q);
		}
		return m;
	}
	for(int pv = 0; pv<3; pv++) for(int q = 0; q<4; q++) {
		int ok = 0;
		switch(an) {
		case AN_LF: case AN_BF: ok = pv==0; break;
		case AN_LL: ok = q==0; break;
		case AN_BL: ok = q<=1; break;
		case AN_WF: ok = pv!=1 && q==2; break;
		case AN_WL: ok = pv==1 && q!=2; break;
		case AN_IW: ok = pv==1 && q==2; break;
		case AN_INW: ok = pv!=1 && q!=2; break;
		}
		if(ok) m |= 1<<(pv*4+q);
	}
	return m;
}

static int gnfa(NF *f, GN *nd, int x, int nx, int sb) {
	if(x<0) return nx;
	GN *g = &nd[x];
	switch(g->t) {
	case GN_CH:
		return nfn(f, NN_CH, nx, 0, g->v+sb);
	case GN_CAT: {
		int b = gnfa(f, nd, g->b, nx, sb);
		return gnfa(f, nd, g->a, b, sb);
	}
	case GN_ALT: {
		int a = gnfa(f, nd, g->a, nx, sb);
		int b = g->b<0 ? nx : gnfa(f, nd, g->b, nx, sb);
		return nfn(f, NN_SPL, a, b, 0);
	}
	case GN_STAR: {
		int s = nfn(f, NN_SPL, 0, nx, 0);
		int a = gnfa(f, nd, g->a, s, sb);
		f->n[s].o1 = a;
		return s;
	}
	case GN_SUB: {
		int e = nfn(f, NN_SAV, nx, 0, g->v*2+1);
		int a = gnfa(f, nd, g->a, e, sb);
		return nfn(f, NN_SAV, a, 0, g->v*2);
	}
	case GN_BREF:
		return nfn(f, NN_BR, nx, 0, g->v);
	case GN_ANC:
		return nfn(f, NN_ASS, nx, 0, gamask(g->v));
	}
	return nx;
}

typedef struct {
	int K;
	uint16_t asc[128];
	uint16_t rawc[128];
	uint16_t top[0x1101];
	uint16_t *pg;
	int npg;
	uint8_t *wk;
	uint8_t *cin;
	int nsets;
} GC;

static void gpart(GC *c, GS *sets, int nsets, uint32_t eol) {
	GS w = {0};
	GS *u = gucls(11);
	for(int i = 0; i<u->n; i++) gsadd(&w, u->r[i].lo, u->r[i].hi);
	gsadd(&w, '_', '_');
	gsnorm(&w);
	int m = nsets+1;
	GS **all = malloc(sizeof(GS*)*(size_t)m);
	for(int i = 0; i<nsets; i++) all[i] = &sets[i];
	all[nsets] = &w;
	uint32_t *pts = malloc(sizeof(uint32_t)*4);
	int np = 0, cp = 4;
	pts[np++] = 0;
	pts[np++] = 0x110001;
	for(int i = 0; i<m; i++) for(int j = 0; j<all[i]->n; j++) {
		if(np+2>cp) {
			cp *= 2;
			pts = realloc(pts, sizeof(uint32_t)*(size_t)cp);
		}
		pts[np++] = all[i]->r[j].lo;
		pts[np++] = all[i]->r[j].hi+1;
	}
	for(int i = 1; i<np; i++) {
		uint32_t v = pts[i];
		int j = i;
		while(j>0 && pts[j-1]>v) {
			pts[j] = pts[j-1];
			j--;
		}
		pts[j] = v;
	}
	int k = 0;
	for(int i = 0; i<np; i++) if(k==0 || pts[k-1]!=pts[i]) pts[k++] = pts[i];
	np = k;
	int sb = (m+7)/8;
	uint8_t *sig = calloc((size_t)(np+129)*(size_t)sb, 1);
	int *ptr = calloc((size_t)m, sizeof(int));
	int *cid = malloc(sizeof(int)*(size_t)(np+129));
	int K = 0;
	uint8_t *csig = malloc((size_t)(np+129)*(size_t)sb);
	for(int i = 0; i+1<np; i++) {
		uint32_t a = pts[i];
		uint8_t *sg = sig+(size_t)i*sb;
		for(int j = 0; j<m; j++) {
			while(ptr[j]<all[j]->n && all[j]->r[ptr[j]].hi<a) ptr[j]++;
			if(ptr[j]<all[j]->n && all[j]->r[ptr[j]].lo<=a) sg[j>>3] |= (uint8_t)(1<<(j & 7));
		}
		int f = -1;
		for(int q = 0; q<K; q++) if(memcmp(csig+(size_t)q*sb, sg, (size_t)sb)==0) { f = q; break; }
		if(f<0) {
			memcpy(csig+(size_t)K*sb, sg, (size_t)sb);
			f = K++;
		}
		cid[i] = f;
	}
	int rc[128];
	for(int b = 0; b<128; b++) {
		uint8_t sg[4096];
		memset(sg, 0, (size_t)sb);
		for(int j = 0; j<nsets; j++) if(sets[j].raw[b>>3] & (1<<(b & 7))) sg[j>>3] |= (uint8_t)(1<<(j & 7));
		int f = -1;
		for(int q = 0; q<K; q++) if(memcmp(csig+(size_t)q*sb, sg, (size_t)sb)==0) { f = q; break; }
		if(f<0) {
			memcpy(csig+(size_t)K*sb, sg, (size_t)sb);
			f = K++;
		}
		rc[b] = f;
	}
	c->K = K;
	c->nsets = nsets;
	c->cin = calloc((size_t)nsets*(size_t)(K+1), 1);
	c->wk = calloc((size_t)K+1, 1);
	for(int q = 0; q<K; q++) {
		for(int j = 0; j<nsets; j++) if(csig[(size_t)q*sb+(j>>3)] & (1<<(j & 7))) c->cin[(size_t)j*(K+1)+q] = 1;
		if(csig[(size_t)q*sb+(nsets>>3)] & (1<<(nsets & 7))) c->wk[q] = 1;
	}
	for(int b = 0; b<128; b++) c->rawc[b] = (uint16_t)rc[b];
	uint16_t *cl = malloc(sizeof(uint16_t)*0x110001);
	for(int i = 0; i+1<np; i++) for(uint32_t x = pts[i]; x<pts[i+1] && x<=0x110000; x++) cl[x] = (uint16_t)cid[i];
	for(int b = 0; b<128; b++) c->asc[b] = cl[b];
	c->asc[eol] = (uint16_t)K;
	c->pg = malloc(sizeof(uint16_t)*256);
	c->npg = 0;
	for(uint32_t pgi = 0; pgi<0x1101; pgi++) {
		uint16_t *src = malloc(sizeof(uint16_t)*256);
		for(int j = 0; j<256; j++) {
			uint32_t x = pgi*256+(uint32_t)j;
			src[j] = x<=0x110000 ? cl[x] : cl[0x110000];
		}
		int f = -1;
		for(int q = 0; q<c->npg; q++) if(memcmp(c->pg+(size_t)q*256, src, 512)==0) { f = q; break; }
		if(f<0) {
			c->pg = realloc(c->pg, sizeof(uint16_t)*256*(size_t)(c->npg+1));
			memcpy(c->pg+(size_t)c->npg*256, src, 512);
			f = c->npg++;
		}
		c->top[pgi] = (uint16_t)f;
		free(src);
	}
	free(cl);
	free(sig);
	free(ptr);
	free(cid);
	free(csig);
	free(pts);
	free(all);
	gsfree(&w);
}

typedef struct {
	int32_t *t;
	uint8_t *acc;
	uint8_t *pv;
	int ns, cs, row;
	int st[3];
	int ovf;
} GD;

typedef struct {
	uint32_t *e;
	int n;
	int pv;
	int acc;
	unsigned h;
} GDS;

#define GD_MAXS 40000

static int *g_tch;
static int g_ntch;
static int g_hass;

static void gdpush(uint8_t *mk, int *wl, int *top, int y, int m) {
	if(!mk[y]) g_tch[g_ntch++] = y;
	mk[y] |= (uint8_t)m;
	wl[(*top)++] = y;
}

static void gdclos(NF *f, int *seed, int ns, int pv, uint8_t *mk, int *wl, int *acc) {
	int top = 0;
	*acc = 0;
	for(int i = 0; i<ns; i++) {
		int x = seed[i];
		if((mk[x] & 0xF)!=0xF) gdpush(mk, wl, &top, x, 0xF);
	}
	while(top) {
		int x = wl[--top];
		int m = mk[x] & 0xF;
		NN *q = &f->n[x];
		int nm, y;
		switch(q->t) {
		case NN_MAT:
			*acc |= m;
			break;
		case NN_SPL:
			y = q->o1;
			if((mk[y] & m)!=m) gdpush(mk, wl, &top, y, m);
			y = q->o2;
			if((mk[y] & m)!=m) gdpush(mk, wl, &top, y, m);
			break;
		case NN_JMP:
		case NN_SAV:
			y = q->o1;
			if((mk[y] & m)!=m) gdpush(mk, wl, &top, y, m);
			break;
		case NN_ASS:
			nm = m & ((q->v>>(pv*4)) & 0xF);
			y = q->o1;
			if(nm && (mk[y] & nm)!=nm) gdpush(mk, wl, &top, y, nm);
			break;
		}
	}
}

static int icmpu(const void *a, const void *b) {
	uint32_t x = *(const uint32_t*)a, y = *(const uint32_t*)b;
	return x<y ? -1 : x>y;
}

typedef struct {
	GDS *s;
	int n, c;
	int *hb;
	int hn;
} GDH;

static unsigned gdhash(GDS *s) {
	unsigned h = (unsigned)s->pv*31u+(unsigned)s->acc*7u;
	for(int i = 0; i<s->n; i++) h = h*16777619u ^ s->e[i];
	return h;
}

static int gdfind(GDH *H, GDS *s, int *isnew) {
	unsigned h = gdhash(s);
	s->h = h;
	int b = (int)(h & (unsigned)(H->hn-1));
	while(H->hb[b]>=0) {
		GDS *o = &H->s[H->hb[b]];
		if(o->h==h && o->n==s->n && o->pv==s->pv && o->acc==s->acc && memcmp(o->e, s->e, sizeof(uint32_t)*(size_t)s->n)==0) {
			*isnew = 0;
			return H->hb[b];
		}
		b = (b+1) & (H->hn-1);
	}
	if(H->n==H->c) {
		H->c = H->c ? H->c*2 : 64;
		H->s = realloc(H->s, sizeof(GDS)*(size_t)H->c);
	}
	H->s[H->n] = *s;
	H->s[H->n].e = malloc(sizeof(uint32_t)*(size_t)(s->n ? s->n : 1));
	memcpy(H->s[H->n].e, s->e, sizeof(uint32_t)*(size_t)s->n);
	H->hb[b] = H->n;
	*isnew = 1;
	if(H->n*2>H->hn) {
		int nh = H->hn*2;
		int *nb = malloc(sizeof(int)*(size_t)nh);
		for(int i = 0; i<nh; i++) nb[i] = -1;
		for(int i = 0; i<=H->n; i++) {
			int q = (int)(H->s[i].h & (unsigned)(nh-1));
			while(nb[q]>=0) q = (q+1) & (nh-1);
			nb[q] = i;
		}
		free(H->hb);
		H->hb = nb;
		H->hn = nh;
	}
	return H->n++;
}

static void gdmk(NF *f, GC *c, int *seed, int ns, int pv, uint8_t *mk, int *wl, GDS *out) {
	int acc;
	g_ntch = 0;
	gdclos(f, seed, ns, pv, mk, wl, &acc);
	out->n = 0;
	for(int i = 0; i<g_ntch; i++) {
		int x = g_tch[i];
		if(f->n[x].t==NN_CH && (mk[x] & 0xF)) out->e[out->n++] = (uint32_t)x<<4 | (mk[x] & 0xF);
		mk[x] = 0;
	}
	if(out->n>1) qsort(out->e, (size_t)out->n, sizeof(uint32_t), icmpu);
	out->pv = g_hass ? pv : 0;
	out->acc = acc;
	(void)c;
}

static int gdfa(NF *f, GC *c, int start, int unanch, GD *d) {
	int K = c->K;
	int row = K+1;
	GDH H = {0};
	H.hn = 1024;
	H.hb = malloc(sizeof(int)*(size_t)H.hn);
	for(int i = 0; i<H.hn; i++) H.hb[i] = -1;
	uint8_t *mk = calloc((size_t)f->nn, 1);
	int *wl = malloc(sizeof(int)*(size_t)f->nn*16+64);
	g_tch = malloc(sizeof(int)*(size_t)f->nn+64);
	int *seed = malloc(sizeof(int)*(size_t)(f->nn+1));
	GDS tmp;
	tmp.e = malloc(sizeof(uint32_t)*(size_t)(f->nn+1));
	memset(d, 0, sizeof(*d));
	d->row = row;
	int isn;
	for(int pv = 0; pv<(unanch ? 1 : 3); pv++) {
		seed[0] = start;
		gdmk(f, c, seed, 1, pv, mk, wl, &tmp);
		d->st[pv] = gdfind(&H, &tmp, &isn);
	}
	g_hass = 0;
	for(int i = 0; i<f->nn; i++) if(f->n[i].t==NN_ASS) g_hass = 1;
	int dok = 1;
	if(unanch) for(int pv = 1; pv<3; pv++) {
		seed[0] = start;
		gdmk(f, c, seed, 1, pv, mk, wl, &tmp);
		if(tmp.n || tmp.acc) dok = 0;
	}
	int cap = 0;
	for(int si = 0; si<H.n; si++) {
		if(H.n>GD_MAXS) {
			d->ovf = 1;
			break;
		}
		if(si>=cap) {
			cap = cap ? cap*2 : 64;
			d->t = realloc(d->t, sizeof(int32_t)*(size_t)cap*(size_t)row);
		}
		for(int k = 0; k<K; k++) {
			GDS *S = &H.s[si];
			int q = c->wk[k] ? 2 : 3;
			int np = c->wk[k] ? 1 : 2;
			if(unanch && (S->acc & (1<<q))) {
				d->t[(size_t)si*row+k] = -1;
				continue;
			}
			int ns = 0;
			for(int i = 0; i<S->n; i++) {
				uint32_t e = S->e[i];
				int x = (int)(e>>4);
				if((e & (1u<<q)) && c->cin[(size_t)f->n[x].v*(size_t)(K+1)+k]) seed[ns++] = f->n[x].o1;
			}
			if(unanch) seed[ns++] = start;
			gdmk(f, c, seed, ns, np, mk, wl, &tmp);
			if(tmp.n==0 && tmp.acc==0 && dok) {
				d->t[(size_t)si*row+k] = -4;
				continue;
			}
			int t = gdfind(&H, &tmp, &isn);
			d->t[(size_t)si*row+k] = t;
		}
		GDS *S = &H.s[si];
		d->t[(size_t)si*row+K] = unanch ? ((S->acc & 1) ? -2 : -3) : -4;
	}
	d->ns = H.n;
	d->acc = malloc((size_t)H.n+1);
	d->pv = malloc((size_t)H.n+1);
	for(int i = 0; i<H.n; i++) {
		d->acc[i] = (uint8_t)H.s[i].acc;
		d->pv[i] = (uint8_t)H.s[i].pv;
		free(H.s[i].e);
	}
	free(H.s);
	free(H.hb);
	free(mk);
	free(wl);
	free(g_tch);
	free(seed);
	free(tmp.e);
	return d->ovf ? -1 : 0;
}

static int gwarn(const unsigned char *p, int n, int ere, char *out, size_t on) {
	int ls = 1, last = 0, parens = 0, i = 0;
	out[0] = 0;
	while(i<n) {
		int c = p[i++], bs = 0;
		if(c=='\\') {
			if(i>=n) return 0;
			bs = 1;
			c = p[i++];
		}
		int tok = 1;
		switch(c) {
		case '^':
			if(bs) break;
			if(ere || last==0 || last==2 || last==3) { tok = 5; goto done; }
			break;
		case '$':
			if(bs) break;
			if(ere || i>=n || (!ere && i+1<n && p[i]=='\\' && (p[i+1]==')' || p[i+1]=='|')) || p[i]=='\n') { tok = 5; goto done; }
			break;
		case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9':
			if(bs) { ls = 0; tok = 1; goto done; }
			break;
		case '`': case '\'': case '<': case '>': case 'b': case 'B':
			if(bs) { tok = 5; goto done; }
			break;
		case '?': case '+': case '*':
			if(c=='*' && bs) break;
			if(c!='*' && bs!=!ere) break;
			if(ls) {
				if(!ere) break;
				snprintf(out+strlen(out), on-strlen(out), "grep: warning: %c at start of expression\n", c);
			}
			tok = 6;
			goto done;
		case '{': {
			if(bs!=!ere) break;
			int q = i, mn = -1, mx = -1;
			for(; q<n && p[q]>='0' && p[q]<='9'; q++) mn = mn<0 ? p[q]-'0' : (mn*10+p[q]-'0'>RE_DUPM+1 ? RE_DUPM+1 : mn*10+p[q]-'0');
			if(q<n) {
				if(p[q]!=',') mx = mn;
				else {
					if(mn<0) mn = 0;
					while(++q<n && p[q]>='0' && p[q]<='9') mx = mx<0 ? p[q]-'0' : (mx*10+p[q]-'0'>RE_DUPM+1 ? RE_DUPM+1 : mx*10+p[q]-'0');
				}
			}
			int inv = !((!bs || (q<n && p[q++]=='\\')) && q<n && p[q++]=='}' && mn>=0 && (mx<0 || mn<=mx));
			if(inv && ere) break;
			if(ls) {
				if(!ere) break;
				snprintf(out+strlen(out), on-strlen(out), "grep: warning: {...} at start of expression\n");
			}
			if(inv) {
				snprintf(out, on, "grep: invalid content of \\{\\}\n");
				return 1;
			}
			if(mx>RE_DUPM) {
				snprintf(out, on, "grep: regular expression too big\n");
				return 1;
			}
			i = q;
			ls = 0;
			tok = 6;
			goto done;
		}
		case '|':
			if(bs!=!ere) break;
			ls = 1;
			tok = 3;
			goto done;
		case '\n':
			if(bs) break;
			ls = 1;
			tok = 3;
			goto done;
		case '(':
			if(bs!=!ere) break;
			parens++;
			ls = 1;
			tok = 2;
			goto done;
		case ')':
			if(bs!=!ere) break;
			if(parens==0 && ere) break;
			parens--;
			ls = 0;
			tok = 4;
			goto done;
		case '.': case 'w': case 'W': case 's': case 'S':
			if((c=='.')==bs) break;
			ls = 0;
			goto done;
		case '[': {
			if(bs) break;
			ls = 0;
			int cws, k = i;
			if(k<n && p[k]=='^') k++;
			int c0 = k<n ? p[k] : 0;
			cws = c0==':';
			int first = 1;
			for(;;) {
				if(k>=n) return 0;
				int ch = p[k++];
				if(ch==']' && !first) break;
				first = 0;
				cws &= ~2;
				if(ch=='[' && k<n && (p[k]==':' || p[k]=='.' || p[k]=='=')) {
					int d = p[k++];
					while(k+1<n && !(p[k]==d && p[k+1]==']')) k++;
					k += 2;
					cws |= 8;
					continue;
				}
				if(k+1<n && p[k]=='-' && p[k+1]!=']') {
					k += 2;
					cws |= 8;
					continue;
				}
				cws |= ch==':' ? 2 : 4;
			}
			if(cws==7) {
				snprintf(out, on, "grep: character class syntax is [[:space:]], not [:space:]\n");
				return 1;
			}
			i = k;
			goto done;
		}
		}
		ls = 0;
		tok = 1;
done:
		last = tok;
	}
	return 0;
}

