#define XP_DB 12272
#define XP_SP0 12280
enum { XO_WARN = 1, XO_FATAL, XO_SOPT, XO_ENV, XO_OUT };

typedef struct { int t; long v; char *s; int rc; } XOp;

typedef struct {
	XOp *op;
	int nop, cop, stop;
	int mode, delim, lpe, ape, xit, otty, pcmd, qry, arun, csig, showl;
	long pmax;
	const char *eofs, *rep, *inf, *slot;
} XS;

static void xop(XS *x, int t, long v, char *s, int rc) {
	if(x->nop==x->cop) {
		x->cop = x->cop ? x->cop*2 : 16;
		x->op = realloc(x->op, sizeof(XOp)*(size_t)x->cop);
	}
	x->op[x->nop].t = t;
	x->op[x->nop].v = v;
	x->op[x->nop].s = s;
	x->op[x->nop].rc = rc;
	x->nop++;
}

static char *xfmt(const char *fmt, ...) {
	char *m;
	va_list ap;
	va_start(ap, fmt);
	if(vasprintf(&m, fmt, ap)<0) m = strdup("");
	va_end(ap);
	return m;
}

static void xdie(XS *x, char *m) {
	char *t = xfmt("%sTry 'xargs --help' for more information.\n", m);
	free(m);
	xop(x, XO_FATAL, 0, t, 1);
	x->stop = 1;
}

static void xmut(XS *x, const char *o, const char *off) {
	xop(x, XO_WARN, 0, xfmt("xargs: warning: options %s and %s are mutually exclusive, ignoring previous %s value\n", off, o, off), 0);
}

static long xnum(XS *x, const char *s, int opt, long mn, long mx, int fatal) {
	char *e;
	long v = strtol(s, &e, 10);
	if(e==s || *e) {
		xdie(x, xfmt("xargs: invalid number \"%s\" for -%c option\n", s, opt));
		return 0;
	}
	if(v<mn) {
		char *m = xfmt("xargs: value %s for -%c option should be >= %ld\n", s, opt, mn);
		if(fatal) xdie(x, m);
		else xop(x, XO_WARN, 0, m, 0);
		return mn;
	}
	if(mx>=0 && v>mx) {
		char *m = xfmt("xargs: value %s for -%c option should be <= %ld\n", s, opt, mx);
		if(fatal) xdie(x, m);
		else xop(x, XO_WARN, 0, m, 0);
		return mx;
	}
	return v;
}

static int xoct(XS *x, const char *s) {
	int base = 8;
	const char *p;
	if(s[1]=='x') { p = s+2; base = 16; }
	else if(isdigit((unsigned char)s[1])) p = s+1;
	else {
		xop(x, XO_FATAL, 0, xfmt("xargs: Invalid escape sequence %s in input delimiter specification.\n", s), 1);
		x->stop = 1;
		return 0;
	}
	errno = 0;
	char *e = NULL;
	unsigned long v = strtoul(p, &e, base);
	if((v==ULONG_MAX && errno==ERANGE) || v>UCHAR_MAX) {
		if(base==16) xop(x, XO_FATAL, 0, xfmt("xargs: Invalid escape sequence %s in input delimiter specification; character values must not exceed %lx.\n", s, (unsigned long)UCHAR_MAX), 1);
		else xop(x, XO_FATAL, 0, xfmt("xargs: Invalid escape sequence %s in input delimiter specification; character values must not exceed %lo.\n", s, (unsigned long)UCHAR_MAX), 1);
		x->stop = 1;
		return 0;
	}
	if(*e) {
		xop(x, XO_FATAL, 0, xfmt("xargs: Invalid escape sequence %s in input delimiter specification; trailing characters %s not recognised.\n", s, e), 1);
		x->stop = 1;
		return 0;
	}
	return (int)(unsigned char)v;
}

static int xdelim(XS *x, const char *s) {
	if(strlen(s)==1) return (unsigned char)s[0];
	if(s[0]=='\\') {
		switch(s[1]) {
		case 'a': return '\a';
		case 'b': return '\b';
		case 'f': return '\f';
		case 'n': return '\n';
		case 'r': return '\r';
		case 't': return '\t';
		case 'v': return '\v';
		case '\\': return '\\';
		default: return xoct(x, s);
		}
	}
	xop(x, XO_FATAL, 0, xfmt("xargs: Invalid input delimiter specification %s: the delimiter must be either a single character or an escape sequence starting with \\.\n", s), 1);
	x->stop = 1;
	return 0;
}

static int xparse(XS *x, int argc, char **argv) {
	static const struct option lo[] = {
		{"null", no_argument, NULL, '0'}, {"arg-file", required_argument, NULL, 'a'}, {"delimiter", required_argument, NULL, 'd'},
		{"eof", optional_argument, NULL, 'e'}, {"replace", optional_argument, NULL, 'I'}, {"max-lines", optional_argument, NULL, 'l'},
		{"max-args", required_argument, NULL, 'n'}, {"open-tty", no_argument, NULL, 'o'}, {"interactive", no_argument, NULL, 'p'},
		{"no-run-if-empty", no_argument, NULL, 'r'}, {"max-chars", required_argument, NULL, 's'}, {"verbose", no_argument, NULL, 't'},
		{"show-limits", no_argument, NULL, 'S'}, {"exit", no_argument, NULL, 'x'}, {"max-procs", required_argument, NULL, 'P'},
		{"process-slot-var", required_argument, NULL, 256}, {"version", no_argument, NULL, 'v'}, {"help", no_argument, NULL, 'h'},
		{NULL, no_argument, NULL, 0}
	};
	FILE *oe = stderr;
	char *eb = NULL;
	size_t en = 0;
	FILE *ms = open_memstream(&eb, &en);
	stderr = ms;
	optind = 0;
	opterr = 1;
	int oc, oi = 0, sp = 0;
	while(!x->stop && (oc = getopt_long(argc, argv, "+0a:E:e::i::I:l::L:n:oprs:txP:d:", lo, &oi))!=-1) {
		switch(oc) {
		case '0':
			sp = 1;
			x->delim = 0;
			break;
		case 'd':
			sp = 1;
			x->delim = xdelim(x, optarg);
			break;
		case 'E': case 'e':
			x->eofs = optarg && *optarg ? optarg : NULL;
			break;
		case 'h':
			xop(x, XO_OUT, 0, (char*)"xargs: --help is not available in sh2elf builds\n", 0);
			x->stop = 1;
			break;
		case 'I': case 'i':
			x->rep = optarg ? optarg : "{}";
			if(x->ape) { xmut(x, "--replace/-I/-i", "--max-args"); x->ape = 0; }
			if(x->lpe) { xmut(x, "--replace/-I/-i", "--max-lines"); x->lpe = 0; }
			break;
		case 'L':
			x->lpe = (int)xnum(x, optarg, 'L', 1, -1, 1);
			if(x->ape) { xmut(x, "-L", "--max-args"); x->ape = 0; }
			if(x->rep) { xmut(x, "-L", "--replace"); x->rep = NULL; }
			break;
		case 'l':
			x->lpe = optarg ? (int)xnum(x, optarg, 'l', 1, -1, 1) : 1;
			if(x->ape) { xmut(x, "--max-lines/-l", "--max-args"); x->ape = 0; }
			if(x->rep) { xmut(x, "--max-lines/-l", "--replace"); x->rep = NULL; }
			break;
		case 'n':
			x->ape = (int)xnum(x, optarg, 'n', 1, -1, 1);
			if(x->lpe) { xmut(x, "--max-args/-n", "--max-lines"); x->lpe = 0; }
			if(x->rep) {
				if(x->ape==1) x->ape = 0;
				else { xmut(x, "--max-args/-n", "--replace"); x->rep = NULL; }
			}
			break;
		case 's': {
			char *e;
			strtol(optarg, &e, 10);
			if(e==optarg || *e) xdie(x, xfmt("xargs: invalid number \"%s\" for -%c option\n", optarg, 's'));
			else xop(x, XO_SOPT, strtol(optarg, NULL, 10), strdup(optarg), 0);
			break;
		}
		case 'S': x->showl = 1; break;
		case 't': x->pcmd = 1; break;
		case 'x': x->xit = 1; break;
		case 'o': x->otty = 1; break;
		case 'p': x->qry = 1; x->pcmd = 1; break;
		case 'r': x->arun = 0; break;
		case 'P':
			x->pmax = xnum(x, optarg, 'P', 0, 2147483647L, 1);
			x->csig = 1;
			break;
		case 'a': x->inf = optarg; break;
		case 'v':
			xop(x, XO_OUT, 0, (char*)"xargs: --version is not available in sh2elf builds\n", 0);
			x->stop = 1;
			break;
		case 256:
			if(strchr(optarg, '=')) {
				xop(x, XO_FATAL, 0, xfmt("xargs: option --%s may not be set to a value which includes `='\n", lo[oi].name), 1);
				x->stop = 1;
			} else x->slot = optarg;
			break;
		default:
			fflush(ms);
			xdie(x, xfmt("%.*s", (int)en, eb ? eb : ""));
			break;
		}
		fflush(ms);
		if(en && !x->stop) {
			xop(x, XO_WARN, 0, xfmt("%.*s", (int)en, eb), 0);
		}
		fclose(ms);
		free(eb);
		eb = NULL;
		en = 0;
		ms = open_memstream(&eb, &en);
		stderr = ms;
	}
	stderr = oe;
	fclose(ms);
	free(eb);
	x->mode = sp;
	if(!x->stop && x->eofs && sp) xop(x, XO_WARN, 0, xfmt("xargs: warning: the -E option has no effect if -0 or -d is used.\n\n"), 0);
	if(!x->stop) xop(x, XO_ENV, 0, NULL, 0);
	return optind;
}

