enum { MK_P = 1, MK_M = 2, MK_V = 4 };

typedef struct { uint64_t op, flag, aff, val, men; } MChg;

static int mcomp(const char *ms, MChg *mc, int *nmc) {
	int used = 0;
	if('0'<=*ms && *ms<'8') {
		const char *p = ms;
		unsigned int om = 0;
		do {
			om = 8*om + (unsigned)(*p++ - '0');
			if(07777<om) return 0;
		} while('0'<=*p && *p<'8');
		if(*p) return 0;
		unsigned int men = (p-ms<5) ? ((om & 06000) | 01000 | 0777) : 07777;
		mc[0] = (MChg){'=', 1, 07777, om, men};
		*nmc = 1;
		return 1;
	}
	const char *p;
	for(p = ms; ; p++) {
		unsigned int aff = 0;
		for(;; p++) {
			switch(*p) {
			case 'u': aff |= 04700; continue;
			case 'g': aff |= 02070; continue;
			case 'o': aff |= 01007; continue;
			case 'a': aff |= 07777; continue;
			case '=': case '+': case '-': break;
			default: return 0;
			}
			break;
		}
		do {
			char op = *p++;
			unsigned int val, men = 0;
			int flag = 3;
			switch(*p) {
			case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': {
				unsigned int om = 0;
				do {
					om = 8*om + (unsigned)(*p++ - '0');
					if(07777<om) return 0;
				} while('0'<=*p && *p<'8');
				if(aff || (*p && *p!=',')) return 0;
				aff = men = 07777;
				val = om;
				flag = 1;
				break;
			}
			case 'u': val = 0700; p++; break;
			case 'g': val = 0070; p++; break;
			case 'o': val = 0007; p++; break;
			default:
				val = 0;
				flag = 1;
				for(;; p++) {
					if(*p=='r') val |= 0444;
					else if(*p=='w') val |= 0222;
					else if(*p=='x') val |= 0111;
					else if(*p=='X') flag = 2;
					else if(*p=='s') val |= 06000;
					else if(*p=='t') val |= 01000;
					else break;
				}
			}
			mc[used++] = (MChg){(uint64_t)op, (uint64_t)flag, aff, val, men ? men : aff ? (aff & val) : val};
		} while(*p=='=' || *p=='+' || *p=='-');
		if(*p!=',') break;
	}
	if(*p) return 0;
	*nmc = used;
	return 1;
}

