	c8(c,0x6B); c8(c,0x20); c8(c,0x6E);
	c8(c,0x6F);
	c8(c,0x74); c8(c,0x20);
	c8(c,0x66); c8(c,0x6F);
	c8(c,0x6C);
	c8(c,0x6C);
	c8(c,0x6F);
	c8(c,0x77); c8(c,0x65);
	c8(c,0x64);
	c8(c,0x00);
