enum { TF_A = 1, TF_M = 2, TF_NOCR = 4, TF_NODR = 8, TF_REF = 16, TF_DATE = 32, TF_DYN = 64, TF_BAD = 128, TF_TSET = 256 };

static long g_tmoff;

static int gleap(long y) {
	return (y & 3)==0 && (y%100!=0 || ((y/100) & 3)==((-(1900/100)) & 3));
}

static long gydhms(long y1, long yd1, int h1, int m1, int s1, int y0, int yd0, int h0, int m0, int s0) {
	int a4 = (int)((y1>>2) + (1900>>2) - !(y1 & 3));
	int b4 = (y0>>2) + (1900>>2) - !(y0 & 3);
	int a100 = (a4+(a4<0))/25-(a4<0);
	int b100 = (b4+(b4<0))/25-(b4<0);
	int a400 = a100>>2;
	int b400 = b100>>2;
	int il = (a4-b4)-(a100-b100)+(a400-b400);
	long years = y1-y0;
	long days = 365*years+yd1-yd0+il;
	long hours = 24*days+h1-h0;
	long mins = 60*hours+m1-m0;
	return 60*mins+s1-s0;
}

static long gtmdiff(long y, long yd, int h, int m, int sec, const struct tm *tp) {
	return gydhms(y, yd, h, m, sec, tp->tm_year, tp->tm_yday, tp->tm_hour, tp->tm_min, tp->tm_sec);
}

static int gdiff(int a, int b) {
	return (!a!=!b) && 0<=a && 0<=b;
}

static time_t gmk(struct tm *tp) {
	static const unsigned short my[2][13] = {{0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334, 365}, {0, 31, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335, 366}};
	struct tm tm;
	int rp = 6;
	int sec = tp->tm_sec, min = tp->tm_min, hour = tp->tm_hour, mday = tp->tm_mday, mon = tp->tm_mon, yr = tp->tm_year, isdst = tp->tm_isdst;
	int dst2 = 0;
	int mr = mon%12, nmr = mr<0, mys = mon/12-nmr;
	long year = (long)yr+mys;
	long yday = (long)my[gleap(year)][mr+12*nmr]-1+mday;
	long off = g_tmoff;
	int sreq = sec;
	if(sec<0) sec = 0;
	if(59<sec) sec = 59;
	long nog = -off;
	long t0 = gydhms(year, yday, hour, min, sec, 70, 0, 0, 0, (int)nog);
	long t = t0, t1 = t0, t2 = t0;
	for(;;) {
		time_t x = t;
		if(!localtime_r(&x, &tm)) return -1;
		long dt = gtmdiff(year, yday, hour, min, sec, &tm);
		if(dt==0) break;
		if(t==t1 && t!=t2 && (tm.tm_isdst<0 || (isdst<0 ? dst2<=(tm.tm_isdst!=0) : (isdst!=0)!=(tm.tm_isdst!=0)))) goto found;
		if(--rp==0) return -1;
		t1 = t2;
		t2 = t;
		t += dt;
		dst2 = tm.tm_isdst!=0;
	}
	if(gdiff(isdst, tm.tm_isdst)) {
		int stride = 601200;
		int bound = 366*24*60*60+1+stride;
		for(int delta = stride; delta<bound; delta += stride)
			for(int dir = -1; dir<=1; dir += 2) {
				long ot = t+(long)delta*dir;
				struct tm otm;
				time_t x = ot;
				if(!localtime_r(&x, &otm)) return -1;
				if(!gdiff(isdst, otm.tm_isdst)) {
					long gt = ot+gtmdiff(year, yday, hour, min, sec, &otm);
					time_t xg = gt;
					if(localtime_r(&xg, &tm)) {
						t = gt;
						goto found;
					}
				}
			}
	}
found:
	g_tmoff = t-t0+nog;
	if(sreq!=tm.tm_sec) {
		long adj = sec==0 && tm.tm_sec==60;
		adj -= sec;
		adj += sreq;
		t += adj;
		time_t x = t;
		if(!localtime_r(&x, &tm)) return -1;
	}
	*tp = tm;
	return t;
}

static int tyear(struct tm *tm, const int *dp, int n, int sb) {
	if(n==1) {
		tm->tm_year = *dp;
		if(dp[0]<=68) {
			if(sb & 2) return 0;
			tm->tm_year += 100;
		}
	} else if(n==2) {
		if(!(sb & 4)) return 0;
		tm->tm_year = dp[0]*100+dp[1]-1900;
	} else {
		time_t now = time(NULL);
		struct tm *tp = localtime(&now);
		if(!tp) return 0;
		tm->tm_year = tp->tm_year;
	}
	return 1;
}

static int tptime(time_t *pt, const char *s, int sb) {
	struct tm tm0;
	size_t sl = strlen(s), len = sl;
	const char *dot = NULL;
	if(sb & 8) {
		dot = strchr(s, '.');
		if(dot) {
			len = (size_t)(dot-s);
			if(sl-len!=3) return 0;
		}
	}
	if(!(8<=len && len<=12 && len%2==0)) return 0;
	for(size_t i = 0; i<len; i++) if(!c_isdigit((unsigned char)s[i])) return 0;
	len /= 2;
	int pair[6];
	for(size_t i = 0; i<len; i++) pair[i] = 10*(s[2*i]-'0')+s[2*i+1]-'0';
	int *p = pair;
	if(!(sb & 1)) {
		if(!tyear(&tm0, p, (int)len-4, sb)) return 0;
		p += len-4;
		len = 4;
	}
	tm0.tm_mon = *p++-1;
	tm0.tm_mday = *p++;
	tm0.tm_hour = *p++;
	tm0.tm_min = *p++;
	len -= 4;
	if(sb & 1) if(!tyear(&tm0, p, (int)len, sb)) return 0;
	if(!dot) tm0.tm_sec = 0;
	else if(c_isdigit((unsigned char)dot[1]) && c_isdigit((unsigned char)dot[2])) tm0.tm_sec = 10*(dot[1]-'0')+dot[2]-'0';
	else return 0;
	int leap = 0;
	for(;;) {
		struct tm t1;
		memset(&t1, 0, sizeof(t1));
		t1.tm_sec = tm0.tm_sec;
		t1.tm_min = tm0.tm_min;
		t1.tm_hour = tm0.tm_hour;
		t1.tm_mday = tm0.tm_mday;
		t1.tm_mon = tm0.tm_mon;
		t1.tm_year = tm0.tm_year;
		t1.tm_wday = -1;
		t1.tm_isdst = -1;
		time_t t = g_mktf(&t1);
		if(t == (time_t)-1 && t1.tm_wday<0) return 0;
		if(t1.tm_wday<0) return 0;
		if(!((tm0.tm_year ^ t1.tm_year) | (tm0.tm_mon ^ t1.tm_mon) | (tm0.tm_mday ^ t1.tm_mday) | (tm0.tm_hour ^ t1.tm_hour) | (tm0.tm_min ^ t1.tm_min) | (tm0.tm_sec ^ t1.tm_sec))) {
			*pt = t+leap;
			return 1;
		}
		if(tm0.tm_sec!=60) return 0;
		tm0.tm_sec = 59;
		leap = 1;
	}
}

