static void tool_chown(Code *c, Gen *g, Stage *st, int us) {
	tchw(c, g, st, us, 1);
}

static void tool_chgrp(Code *c, Gen *g, Stage *st, int us) {
	tchw(c, g, st, us, 0);
}

